#!/usr/bin/perl
# Verification script for primers.fasta
# Checks all task constraints using oligotm as ground truth.
use strict;
use warnings;

my $fail = 0;
sub check { my($cond, $msg) = @_; print ($cond ? "PASS: $msg\n" : "FAIL: $msg\n"); $fail=1 unless $cond; }

